"""Read-only full inventory and model/document delivery verification."""
from pathlib import Path
import sys,json,hashlib
T=Path(sys.argv[1]);B=T/'experiment';R=B/'round17';m=json.loads((T/'交付文件清单.json').read_text(encoding='utf-8-sig'));qa=json.loads((B/'model_comparison_20261005/docs/report_qa_task_revision/verification.json').read_text(encoding='utf-8-sig'));s=json.loads((R/'results/summary.json').read_text(encoding='utf-8'));v=json.loads((R/'results/independent_verification.json').read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
checks={};checks['round17_complete']=(R/'results/pipeline_complete.json').exists();checks['model_implementation_verified']=v['all_passed'];checks['correct_retained_model']=m['selected_model']=='round8b' and s['selection']['chosen_alpha']==0;checks['no_false_winner']=not m['all_metric_goal_met'] and not s['all_metric_test_candidate_dominance'];checks['report_current_and_reviewed']=qa['all_passed'] and qa['all_pages_visually_reviewed'] and qa['pages']==16 and qa['document_sha256']==sha(T/'Google PowerData 2019 三项预测任务与模型比较汇报.docx')==m['report_sha256'];checks['all16_pages']=qa['page_numbers_reviewed']==list(range(1,17));checks['page_hashes']=all(sha(Path(a['file']))==a['sha256'] for a in qa['images']);checks['csv_and_record_present']=(T/'联合优化三轮多维度对照.csv').exists() and (T/'第17轮多跨度残差优化记录.md').exists();checks['inventory_entries_unique']=len(m['all_files'])==len({a['path'] for a in m['all_files']})==m['files'];checks['all_inventory_files_exist_and_sizes']=all((T/a['path']).is_file() and (T/a['path']).stat().st_size==a['bytes'] for a in m['all_files']);checks['inventory_total_bytes']=sum(a['bytes'] for a in m['all_files'])==m['bytes'];actual={str(p.relative_to(T)) for p in T.rglob('*') if p.is_file() and p.name!='交付文件清单.json'};checks['no_missing_new_files']=actual=={a['path'] for a in m['all_files']};checks['physical_root_d']=str(T.resolve()).startswith('D:');checks['guard_finished']=json.loads((R/'results/resource_status.json').read_text())['stage']=='completed'
assert all(checks.values()),checks
print(json.dumps(dict(all_passed=True,checks=checks,files=m['files'],bytes=m['bytes'],word_pages=16,all_metric_goal_met=False),ensure_ascii=False))
